```dart
import 'dart:typed_data';
import 'package:camera/camera.dart';
import 'package:image/image.dart' as img;

/// Converts a [CameraImage] to a PNG-encoded [Uint8List].
Future<Uint8List> convertCameraImageToPng(CameraImage cameraImage) async {
  final int width = cameraImage.width;
  final int height = cameraImage.height;
  final planes = cameraImage.planes;

  // Create an RGB image of the same dimensions
  final img.Image image = img.Image(width, height);

  for (int y = 0; y < height; y++) {
    for (int x = 0; x < width; x++) {
      final plane0 = planes[0];

      // Calculate Y value
      final int yIndex = y * plane0.bytesPerRow + x * plane0.pixelStride;
      final int Y = plane0.bytes[yIndex];

      int U = 0, V = 0;

      // Extract U and V components depending on the number of planes
      if (planes.length == 3) {
        // YUV420: separate Y, U, V planes
        final plane1 = planes[1];
        final plane2 = planes[2];

        final int uvY = y ~/ 2;
        final int uvX = x ~/ 2;

        final int uIndex = uvY * plane1.bytesPerRow + uvX * plane1.pixelStride;
        final int vIndex = uvY * plane2.bytesPerRow + uvX * plane2.pixelStride;

        U = plane1.bytes[uIndex];
        V = plane2.bytes[vIndex];
      } else if (planes.length == 2) {
        // NV21: single Y plane and interleaved VU plane
        final plane1 = planes[1];

        final int uvY = y ~/ 2;
        final int uvX = x ~/ 2;

        final int uvIndex = uvY * plane1.bytesPerRow + uvX * plane1.pixelStride;

        V = plane1.bytes[uvIndex];
        U = plane1.bytes[uvIndex + 1];
      }

      // YUV to RGB conversion (standard limited range conversion)
      double r = 1.164 * (Y - 16) + 1.596 * (V - 128);
      double g = 1.164 * (Y - 16) - 0.813 * (V - 128) - 0.391 * (U - 128);
      double b = 1.164 * (Y - 16) + 2.018 * (U - 128);

      // Clamp to byte values [0, 255]
      r = r.clamp(0, 255);
      g = g.clamp(0, 255);
      b = b.clamp(0, 255);

      // Set RGB value in the output image
      image.setPixelRgb8(x, y, r.toInt(), g.toInt(), b.toInt());
    }
  }

  // Convert the image to PNG
  final List<int> pngBytes = img.encodePng(image);

  return Uint8List.fromList(pngBytes);
}
```

